170	export function fmtBytes(b: number): string {
171	  if (!b || b <= 0) return "0 B";
172	  const units = ["B", "KB", "MB", "GB", "TB", "PB"];
173	  const i = Math.min(Math.floor(Math.log(b) / Math.log(1024)), units.length - 1);
174	  return `${(b / 1024 ** i).toFixed(1)} ${units[i]}`;
175	}
176	
177	export function fmtMoney(cents: number): string {
178	  return `$${(cents / 100).toFixed(2)}`;
179	}
180	
181	export function timeAgo(d: Date): string {
182	  const s = Math.floor((Date.now() - d.getTime()) / 1000);
183	  if (s < 60) return `${s}s ago`;
184	  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
185	  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
186	  return `${Math.floor(s / 86400)}d ago`;
187	}
