/// Append-only log of a rule evaluation (dry-run). `matched` = the condition
/// held; `note` = a human summary of what the rule WOULD have done. No mutation
/// is ever performed in Phase 1.
model AdsRuleRun {
  id      String   @id @default(cuid())
  ruleId  String
  ranAt   DateTime @default(now())
  matched Boolean  @default(false)
  note    String   @default("")

  rule AdsRule @relation(fields: [ruleId], references: [id], onDelete: Cascade)

  @@index([ruleId])
  @@index([ranAt])
}

enum AdsPlatform {
  META
  TIKTOK
  GOOGLE
}

/// Connection state of an ad account. Phase 1 never truly connects: "Connect"
/// only marks CONNECTED_STUB to demonstrate the flow — real OAuth + platform
/// app-review approval is required to reach a genuine connected state.
enum AdsAccountStatus {
  DISCONNECTED
  CONNECTED_STUB
}

/// Lifecycle shared by campaigns, ad sets, creatives and ads. All entities are
/// local drafts in Phase 1 (nothing is pushed to a live platform).
enum AdsEntityStatus {
  DRAFT
  ACTIVE
  PAUSED
  ARCHIVED
}

/// Which entity level an insight row measures. Exactly one of the matching
/// scope FKs (campaignId / adSetId / adId) is set.
enum AdsInsightScope {
  CAMPAIGN
  ADSET
  AD
}

/// A connected (or stub-connected) ad account on one platform. `externalId` is
/// the platform's own account id (e.g. Meta act_123, Google MCC child, TikTok
/// advertiser id) — recorded, never fetched live in Phase 1.
model AdsAccount {
  id          String           @id @default(cuid())
  platform    AdsPlatform
  externalId  String
  name        String
  status      AdsAccountStatus @default(DISCONNECTED)
  connectedAt DateTime?
  createdAt   DateTime         @default(now())
  updatedAt   DateTime         @updatedAt

  campaigns AdsCampaign[]
  rules     AdsRule[]

  @@unique([platform, externalId])
  @@index([platform])
  @@index([status])
  @@index([createdAt])
}

/// A campaign draft. `objective` is a free-text platform objective label (e.g.
/// OUTCOME_SALES, LEAD_GENERATION). `platform` is denormalized from the account
/// for cheap cross-platform reporting queries.
model AdsCampaign {
  id               String          @id @default(cuid())
  accountId        String
  platform         AdsPlatform
  name             String
  objective        String          @default("")
  status           AdsEntityStatus @default(DRAFT)
  dailyBudgetCents Int             @default(0)
  externalId       String?
  createdAt        DateTime        @default(now())
  updatedAt        DateTime        @updatedAt

  account  AdsAccount   @relation(fields: [accountId], references: [id], onDelete: Cascade)
  adSets   AdsAdSet[]
  insights AdsInsight[]

  @@index([accountId])
  @@index([platform])
  @@index([status])
  @@index([createdAt])
}

/// An ad set (Meta) / ad group (Google/TikTok). `targetingJson` holds a
/// normalized, platform-agnostic targeting blob (audience, geo, placements).
model AdsAdSet {
  id            String          @id @default(cuid())
  campaignId    String
  name          String
  targetingJson Json            @default("{}")
  budgetCents   Int             @default(0)
  status        AdsEntityStatus @default(DRAFT)
  createdAt     DateTime        @default(now())
  updatedAt     DateTime        @updatedAt

  campaign  AdsCampaign   @relation(fields: [campaignId], references: [id], onDelete: Cascade)
  creatives AdsCreative[]
  ads       AdsAd[]
  insights  AdsInsight[]

  @@index([campaignId])
  @@index([status])
}

/// A creative asset (headline + body + optional image reference). `imageRef` is
/// an opaque reference (a Nxeon asset id or URL) — no upload happens in Phase 1.
model AdsCreative {
  id        String          @id @default(cuid())
  adSetId   String
  name      String
  headline  String          @default("")
  body      String          @default("")
  imageRef  String?
  status    AdsEntityStatus @default(DRAFT)
  createdAt DateTime        @default(now())
  updatedAt DateTime        @updatedAt

  adSet AdsAdSet @relation(fields: [adSetId], references: [id], onDelete: Cascade)
  ads   AdsAd[]

  @@index([adSetId])
  @@index([status])
}

/// An ad = a creative placed in an ad set.
model AdsAd {
  id         String          @id @default(cuid())
  adSetId    String
  creativeId String
  name       String
  status     AdsEntityStatus @default(DRAFT)
  createdAt  DateTime        @default(now())
  updatedAt  DateTime        @updatedAt

  adSet    AdsAdSet     @relation(fields: [adSetId], references: [id], onDelete: Cascade)
  creative AdsCreative  @relation(fields: [creativeId], references: [id], onDelete: Cascade)
  insights AdsInsight[]

  @@index([adSetId])
  @@index([creativeId])
  @@index([status])
}

/// A daily metrics row (the reporting fact table). Scope-tagged: exactly one of
/// campaignId / adSetId / adId is populated per `scope`. Phase 1 holds stub /
/// sample data only — never a live insights pull. Revenue/ROAS are omitted on
/// purpose (Phase 1 keeps the canonical set to what stub data can honestly
/// provide: impressions, clicks, spend, conversions).
model AdsInsight {

