/**
 * Sitewave — DETERMINISTIC renderer: Site IR -> self-contained static HTML.
 *
 * Pure + deterministic (same IR in => byte-identical HTML out, no clock, no
 * randomness, no network). Produces a single self-contained page: inline CSS,
 * no external requests, no re-hosted assets.
 *
 * LEGAL GUARDRAILS baked in (architecture §11 — the biggest risk):
 *  - The business NAME appears in plain type only. No logo is referenced or
 *    re-hosted.
 *  - An INSPIRED-BY / neutral palette (from the IR's palette suggestion) — the
 *    renderer never claims to reproduce the business's exact brand.
 *  - A visible "Independent concept — not affiliated with {business}" disclaimer
 *    in the header banner AND the footer.
 *  - <meta name="robots" content="noindex, nofollow"> so the demo can never rank
 *    or be mistaken for the real site.
 *
 * All IR-derived text is HTML-escaped — the renderer never injects raw markup.
 */

import type { SiteIR } from "./schema";
import { SITEWAVE, disclaimerFor } from "./config";

/** Escape the five HTML-significant characters. */
export function esc(s: string): string {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/** Sanitize a hex color to a safe `#rrggbb`, else a neutral default. */
function safeHex(v: string, fallback: string): string {
  return /^#[0-9a-fA-F]{6}$/.test(v) ? v : fallback;
}

export type RenderResult = {
  html: string;
  /** True when every mandatory legal guardrail is present in the output. */
  guardrailsOk: boolean;
};

/**
 * Render a validated Site IR to a complete HTML document string. Never throws.
 */
export function renderSiteHtml(ir: SiteIR): RenderResult {
  const name = esc(ir.businessName || "This business");
  const primary = safeHex(ir.palette.primary, SITEWAVE.palette.indigo);
  const accent = safeHex(ir.palette.accent, SITEWAVE.palette.coral);
  const disclaimer = esc(disclaimerFor(ir.businessName));
  const year = 2026; // fixed so output is deterministic (no Date.now()).

  const services = ir.services
    .map(
      (s) => `        <div class="card">
          <h3>${esc(s.name)}</h3>
          <p>${esc(s.description)}</p>
        </div>`
    )
    .join("\n");

  const testimonials = ir.testimonials
    .map(
      (t) => `        <figure class="quote">
          <blockquote>&ldquo;${esc(t.quote)}&rdquo;</blockquote>
          <figcaption>${esc(t.author)}</figcaption>
        </figure>`
    )

