/// ============================================================================
/// Marketing Hub — Studio / Assets / Calendar (additive, Phase 1)
///
/// The creative Studio renders on-brand SVG creatives (stored as `svg` text +
/// the `paramsJson` field values that produced them). The browser rasterizes to
/// PNG client-side via canvas — NO server-side image library is involved.
///
/// The Calendar/Posting queue is DRAFT + SCHEDULE + manual "mark posted"
/// bookkeeping + export only. Nothing here posts to Instagram/Meta/Reddit/X or
/// sends anything: channel connectors are stubs (no ad/social API access yet).
/// ============================================================================

enum MarketingAssetKind {
  POST // square feed post, 1080×1080
  STORY // vertical story, 1080×1920
  BANNER // link/OG banner, 1200×628
  VIDEO_FRAME // 16:9 title card, 1920×1080
}

/// Distribution surface. Reused by both a post's target channel and a
/// MarketingChannel connector row. BLOG is Nxeon's own blog (the only surface
/// that could ever be posted to without a third-party API).
enum MarketingChannelKind {
  INSTAGRAM
  FACEBOOK
  REDDIT
  X
  BLOG
}

/// A post's lifecycle. POSTED is set by a human AFTER posting by hand (an
/// operator pastes the external URL) — never by an API call.
enum MarketingPostStatus {
  DRAFT
  SCHEDULED
  POSTED
  CANCELLED
}

/// A saved creative produced in the Studio. `svg` is the full, self-contained
/// SVG document; `paramsJson` holds the editable field values (headline,
/// subhead, offer, coupon, cta, domain) so the creative can be re-opened and
/// tweaked. The PNG is produced in-browser from `svg` — never stored.
model MarketingAsset {
  id          String             @id @default(cuid())
  kind        MarketingAssetKind @default(POST)
  title       String             @default("")
  format      String             @default("") // human label, e.g. "IG post 1080²"
  width       Int                @default(1080)
  height      Int                @default(1080)
  templateKey String
  paramsJson  Json               @default("{}")
  svg         String // rendered SVG text (self-contained)
  createdAt   DateTime           @default(now())

  posts MarketingPost[]

  @@index([kind])
  @@index([createdAt])
}

/// A planned social/blog post. `assetId` optionally attaches a saved creative.
/// `scheduledFor` is intent only — nothing dispatches automatically. `postedAt`
/// / `externalUrl` are filled by an operator once they have posted manually.
model MarketingPost {
  id           String               @id @default(cuid())
  channel      MarketingChannelKind
  caption      String               @default("")
  assetId      String?
  scheduledFor DateTime?
  status       MarketingPostStatus  @default(DRAFT)
  postedAt     DateTime?
  externalUrl  String?
  createdAt    DateTime             @default(now())
  updatedAt    DateTime             @updatedAt

  asset MarketingAsset? @relation(fields: [assetId], references: [id], onDelete: SetNull)

  @@index([channel])
  @@index([status])
  @@index([scheduledFor])
  @@index([createdAt])
}

/// A channel connector. `connected` is ALWAYS false until real API access +
/// platform app-review exists — the "Connect" button only records the intent
/// and a note; it never opens a network connection.
model MarketingChannel {
  id        String               @id @default(cuid())
  kind      MarketingChannelKind
  handle    String               @default("")
  connected Boolean              @default(false)
  note      String               @default("")
  createdAt DateTime             @default(now())
  updatedAt DateTime             @updatedAt

  @@unique([kind])
  @@index([kind])
}

