/**
 * Nxeon creative templates — PURE, SHARED, no imports, no side effects.
 *
 * `renderTemplate(key, values)` returns a complete, self-contained SVG document
 * string using the Nxeon brand palette. The same module is consumed by the
 * Studio client component (live preview + client-side PNG rasterization) and by
 * the server action that persists the SVG on a MarketingAsset — so it MUST stay
 * free of any server-only or browser-only APIs.
 *
 * Visual language ported from the Nxeon brand ad creatives: navy field, a
 * violet→cyan gradient bar, a bold headline, an offer pill, a coupon chip, a
 * CTA button and a logo lockup with the domain.
 */

/** Nxeon brand palette. */
export const PALETTE = {
  navy: "#0B1224",
  panel: "#141E3A",
  panel2: "#182647",
  violet: "#7C5CFF",
  cyan: "#22D3EE",
  green: "#34D399",
  ink: "#EAF0FF",
  muted: "#9FB0D9",
} as const;

/** The system font stack — no external font is referenced, so the SVG rasterizes cleanly. */
const FONT =
  "'Inter','Segoe UI',system-ui,-apple-system,'Helvetica Neue',Arial,sans-serif";

export type TemplateKey = "ig-post" | "story" | "banner" | "video-frame";

export type TemplateValues = {
  headline: string;
  subhead: string;
  offer: string;
  coupon: string;
  cta: string;
  domain: string;
};

export type TemplateDef = {
  key: TemplateKey;
  label: string;
  /** Matches the Prisma MarketingAssetKind enum. */
  kind: "POST" | "STORY" | "BANNER" | "VIDEO_FRAME";
  width: number;
  height: number;
  /** Short human label, stored on the asset. */
  format: string;
  /** Editable field defaults for a fresh creative. */
  defaults: TemplateValues;
};

export const TEMPLATES: TemplateDef[] = [
  {
    key: "ig-post",
    label: "Instagram post",
    kind: "POST",
    width: 1080,
    height: 1080,
    format: "IG post · 1080²",
    defaults: {
      headline: "Ship your site on a\nblazing-fast VPS",
      subhead: "NVMe storage, root access and a one-click stack — from $4/mo.",
      offer: "50% OFF first 3 months",
      coupon: "LAUNCH50",
      cta: "Deploy in minutes",
      domain: "nxeon.cloud",
    },
  },
  {
    key: "story",
    label: "Story / Reel",
    kind: "STORY",
    width: 1080,
    height: 1920,
    format: "Story · 1080×1920",
    defaults: {
      headline: "Your idea\ndeserves real\nhardware",
      subhead: "Cloud VPS hosting built for builders. Spin one up today.",
      offer: "Free migration included",
      coupon: "MOVE2NXEON",
      cta: "Swipe up to start",
      domain: "nxeon.cloud",
    },
  },
  {
    key: "banner",
    label: "Link / OG banner",
    kind: "BANNER",
    width: 1200,
    height: 628,
    format: "Banner · 1200×628",
    defaults: {
      headline: "Fast, honest cloud hosting",
      subhead: "VPS, web hosting and email — no lock-in, no surprises.",
      offer: "New: managed web hosting",
      coupon: "",
      cta: "See plans",
      domain: "nxeon.cloud",
    },
  },
  {
    key: "video-frame",
    label: "Video title card",
    kind: "VIDEO_FRAME",
    width: 1920,
    height: 1080,
    format: "Video frame · 1920×1080",
    defaults: {
      headline: "Meet Nxeon",
      subhead: "The developer-first cloud that gets out of your way.",
      offer: "",
      coupon: "",
      cta: "nxeon.cloud",
      domain: "nxeon.cloud",
    },
  },
];

export function templateByKey(key: string): TemplateDef {
  return TEMPLATES.find((t) => t.key === key) ?? TEMPLATES[0];
}

/** Escape the five XML-significant characters so user text can never break the SVG. */
export function escapeXml(s: string): string {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/** Merge caller values over the template defaults, keeping every field a string. */
function withDefaults(def: TemplateDef, values: Partial<TemplateValues>): TemplateValues {
  return {
    headline: values.headline ?? def.defaults.headline,
    subhead: values.subhead ?? def.defaults.subhead,
    offer: values.offer ?? def.defaults.offer,
    coupon: values.coupon ?? def.defaults.coupon,
    cta: values.cta ?? def.defaults.cta,
    domain: values.domain ?? def.defaults.domain,
  };
}

/** Split a headline on explicit newlines, trimmed, capped to `max` lines. */
function headlineLines(text: string, max: number): string[] {
  const lines = String(text ?? "")
    .split("\n")
    .map((l) => l.trim())
    .filter(Boolean);
  return (lines.length ? lines : [""]).slice(0, max);
}

/** Shared <defs> (gradients) — `id` namespaced so multiple SVGs can coexist in one DOM. */
function defs(id: string): string {
  return `<defs>
    <linearGradient id="bar-${id}" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0" stop-color="${PALETTE.violet}"/>
      <stop offset="1" stop-color="${PALETTE.cyan}"/>
    </linearGradient>
    <linearGradient id="bg-${id}" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="${PALETTE.navy}"/>
      <stop offset="1" stop-color="${PALETTE.panel}"/>
    </linearGradient>
    <radialGradient id="glow-${id}" cx="0.82" cy="0.12" r="0.9">
      <stop offset="0" stop-color="${PALETTE.violet}" stop-opacity="0.35"/>
      <stop offset="0.5" stop-color="${PALETTE.violet}" stop-opacity="0.05"/>
      <stop offset="1" stop-color="${PALETTE.violet}" stop-opacity="0"/>
    </radialGradient>
  </defs>`;
}

/** The logo lockup: a gradient glyph + "Nxeon" wordmark + domain. */
function lockup(x: number, y: number, domain: string, scale = 1): string {
  const g = 34 * scale;
  const word = 40 * scale;
  const dom = 22 * scale;
  return `<g transform="translate(${x} ${y})">
    <rect x="0" y="${-g}" width="${g}" height="${g}" rx="${8 * scale}" fill="url(#bar-lock)"/>
    <text x="${g / 2}" y="${-g / 2}" font-family="${FONT}" font-size="${g * 0.62}" font-weight="800" fill="${PALETTE.navy}" text-anchor="middle" dominant-baseline="central">N</text>
    <text x="${g + 16 * scale}" y="${-g * 0.28}" font-family="${FONT}" font-size="${word}" font-weight="800" fill="${PALETTE.ink}">Nxeon</text>
    <text x="${g + 16 * scale}" y="${dom * 0.9}" font-family="${FONT}" font-size="${dom}" font-weight="600" fill="${PALETTE.cyan}">${escapeXml(domain)}</text>
  </g>`;
}

/** A rounded pill with centered text; auto-widths from character count. */
function pill(
  x: number,
  y: number,
  text: string,
  opts: { fill: string; textColor: string; fontSize: number; bold?: boolean }
): string {
  const t = escapeXml(text);
  const padX = opts.fontSize * 0.9;
  const w = t.length * opts.fontSize * 0.58 + padX * 2;
  const h = opts.fontSize * 2.1;
  return `<g transform="translate(${x} ${y})">
    <rect x="0" y="0" width="${Math.round(w)}" height="${Math.round(h)}" rx="${h / 2}" fill="${opts.fill}"/>
    <text x="${w / 2}" y="${h / 2}" font-family="${FONT}" font-size="${opts.fontSize}" font-weight="${opts.bold ? 800 : 700}" fill="${opts.textColor}" text-anchor="middle" dominant-baseline="central">${t}</text>
  </g>`;
}

/**
 * Render a template to a complete SVG document string. Never throws; unknown
 * keys fall back to the IG post. The lockup gradient uses a fixed `bar-lock`
 * id, defined once per document alongside the namespaced background gradients.
 */
export function renderTemplate(key: string, values: Partial<TemplateValues>): string {
  const def = templateByKey(key);
  const v = withDefaults(def, values);
  const { width: W, height: H } = def;
  const id = def.key;

  // Shared framing: background, glow, gradient bar and the lockup gradient def.
  const frame = `${defs(id)}
    <linearGradient id="bar-lock" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0" stop-color="${PALETTE.violet}"/>
      <stop offset="1" stop-color="${PALETTE.cyan}"/>
    </linearGradient>
    <rect width="${W}" height="${H}" fill="url(#bg-${id})"/>
    <rect width="${W}" height="${H}" fill="url(#glow-${id})"/>`;

  if (def.key === "story") return renderStory(W, H, v, frame);
  if (def.key === "banner") return renderBanner(W, H, v, frame);
  if (def.key === "video-frame") return renderVideoFrame(W, H, v, frame);
  return renderPost(W, H, v, frame);
}

function svgDoc(W: number, H: number, body: string): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img">${body}</svg>`;
}

function renderPost(W: number, H: number, v: TemplateValues, frame: string): string {
  const M = 96; // margin
  const lines = headlineLines(v.headline, 3);
  const hSize = lines.length >= 3 ? 92 : 108;
  const top = 300;
  const headline = lines
    .map(
      (ln, i) =>
        `<text x="${M}" y="${top + i * (hSize * 1.12)}" font-family="${FONT}" font-size="${hSize}" font-weight="800" fill="${PALETTE.ink}">${escapeXml(ln)}</text>`
    )
    .join("");
  const subY = top + lines.length * (hSize * 1.12) + 28;
  return svgDoc(
    W,
    H,
    `${frame}
    <rect x="${M}" y="150" width="${W - M * 2}" height="10" rx="5" fill="url(#bar-ig-post)"/>
    ${v.offer ? pill(M, 200, v.offer, { fill: PALETTE.violet, textColor: PALETTE.navy, fontSize: 34, bold: true }) : ""}
    ${headline}
    <text x="${M}" y="${subY}" font-family="${FONT}" font-size="40" font-weight="500" fill="${PALETTE.muted}">${escapeXml(v.subhead)}</text>
    ${v.cta ? pill(M, H - 240, v.cta, { fill: PALETTE.cyan, textColor: PALETTE.navy, fontSize: 40, bold: true }) : ""}
    ${v.coupon ? `<g transform="translate(${M} ${H - 240})"><rect x="0" y="0" width="1" height="1" fill="none"/></g>` : ""}
    ${v.coupon ? pill(M + 360, H - 236, `Code ${v.coupon}`, { fill: PALETTE.panel2, textColor: PALETTE.cyan, fontSize: 32 }) : ""}
    ${lockup(M, H - 96, v.domain)}`
  );
}

function renderStory(W: number, H: number, v: TemplateValues, frame: string): string {
  const M = 96;
  const lines = headlineLines(v.headline, 4);
  const hSize = 110;
  const top = 560;
  const headline = lines
    .map(
      (ln, i) =>
        `<text x="${M}" y="${top + i * (hSize * 1.08)}" font-family="${FONT}" font-size="${hSize}" font-weight="800" fill="${PALETTE.ink}">${escapeXml(ln)}</text>`
    )
    .join("");
  const subY = top + lines.length * (hSize * 1.08) + 40;
  return svgDoc(
    W,
    H,
    `${frame}
    <rect x="${M}" y="360" width="${W - M * 2}" height="10" rx="5" fill="url(#bar-story)"/>
    ${v.offer ? pill(M, 410, v.offer, { fill: PALETTE.violet, textColor: PALETTE.navy, fontSize: 36, bold: true }) : ""}
    ${headline}
    <text x="${M}" y="${subY}" font-family="${FONT}" font-size="44" font-weight="500" fill="${PALETTE.muted}">${escapeXml(v.subhead)}</text>
    ${v.coupon ? pill(M, subY + 60, `Code ${v.coupon}`, { fill: PALETTE.panel2, textColor: PALETTE.cyan, fontSize: 36 }) : ""}
    ${v.cta ? pill(M, H - 320, v.cta, { fill: PALETTE.cyan, textColor: PALETTE.navy, fontSize: 44, bold: true }) : ""}
    ${lockup(M, H - 140, v.domain, 1.15)}`
  );
}

function renderBanner(W: number, H: number, v: TemplateValues, frame: string): string {
  const M = 72;
  const lines = headlineLines(v.headline, 2);
  const hSize = 64;
  const top = 210;
  const headline = lines
    .map(
      (ln, i) =>
        `<text x="${M}" y="${top + i * (hSize * 1.12)}" font-family="${FONT}" font-size="${hSize}" font-weight="800" fill="${PALETTE.ink}">${escapeXml(ln)}</text>`
    )
    .join("");
  const subY = top + lines.length * (hSize * 1.12) + 18;
  return svgDoc(
    W,
    H,
    `${frame}
    <rect x="${M}" y="96" width="${W - M * 2}" height="8" rx="4" fill="url(#bar-banner)"/>
    ${v.offer ? pill(M, 128, v.offer, { fill: PALETTE.violet, textColor: PALETTE.navy, fontSize: 26, bold: true }) : ""}
    ${headline}
    <text x="${M}" y="${subY}" font-family="${FONT}" font-size="30" font-weight="500" fill="${PALETTE.muted}">${escapeXml(v.subhead)}</text>
    ${v.cta ? pill(M, H - 150, v.cta, { fill: PALETTE.cyan, textColor: PALETTE.navy, fontSize: 30, bold: true }) : ""}
    ${lockup(W - 340, H - 72, v.domain, 0.82)}`
  );
}

function renderVideoFrame(W: number, H: number, v: TemplateValues, frame: string): string {
  const lines = headlineLines(v.headline, 2);
  const hSize = 132;
  const cx = W / 2;
  const top = H / 2 - (lines.length - 1) * (hSize * 0.56) - 20;
  const headline = lines
    .map(
      (ln, i) =>
        `<text x="${cx}" y="${top + i * (hSize * 1.12)}" font-family="${FONT}" font-size="${hSize}" font-weight="800" fill="${PALETTE.ink}" text-anchor="middle">${escapeXml(ln)}</text>`
    )
    .join("");
  const subY = top + lines.length * (hSize * 1.12) + 10;
  return svgDoc(
    W,
    H,
    `${frame}
    <rect x="${cx - 90}" y="${top - 150}" width="180" height="9" rx="4" fill="url(#bar-video-frame)"/>
    ${headline}
    <text x="${cx}" y="${subY}" font-family="${FONT}" font-size="46" font-weight="500" fill="${PALETTE.muted}" text-anchor="middle">${escapeXml(v.subhead)}</text>
    ${lockup(cx - 150, H - 90, v.domain)}`
  );
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { logEvent } from "./log";
import { askClaude, effectiveKeyFor } from "./anthropic";
import { renderTemplate, templateByKey, type TemplateValues } from "./marketing/templates";
import type { MarketingAssetKind, MarketingChannelKind, MarketingPostStatus } from "@prisma/client";

/**
 * Marketing Hub — Studio / Assets / Calendar server actions.
 *
 * Every export re-checks requireArea("platform"). HARD GUARDRAILS:
 *  - NOTHING here posts to Instagram/Meta/Reddit/X or sends anything. Channel
 *    "Connect" is a bookkeeping stub (connected stays false; no network).
 *  - The stored SVG is ALWAYS re-rendered server-side from the trusted template
 *    + field values — never accepted verbatim from the client — so a creative
 *    can never smuggle arbitrary markup into the DB.
 *  - Rasterization to PNG happens in the browser (canvas); the server only ever
 *    deals in the SVG text + params.
 */

const STUDIO = "/admin/marketing/studio";
const ASSETS = "/admin/marketing/assets";
const CALENDAR = "/admin/marketing/calendar";

export type ActionState = { error?: string; ok?: boolean; id?: string };

const CHANNELS: MarketingChannelKind[] = ["INSTAGRAM", "FACEBOOK", "REDDIT", "X", "BLOG"];

function str(fd: FormData, key: string, max = 2000): string {
  const v = fd.get(key);
  return typeof v === "string" ? v.slice(0, max).trim() : "";
}

/** Collect the six editable template fields from a form. */
function readValues(fd: FormData): TemplateValues {
  return {
    headline: str(fd, "headline", 240),
    subhead: str(fd, "subhead", 400),
    offer: str(fd, "offer", 120),
    coupon: str(fd, "coupon", 60),
    cta: str(fd, "cta", 80),
    domain: str(fd, "domain", 120),
  };
}

// ---------------------------------------------------------------------------
// Studio / Assets
// ---------------------------------------------------------------------------

/** Persist a creative: re-render the SVG server-side from the chosen template. */
export async function saveAsset(_prev: ActionState, fd: FormData): Promise<ActionState> {
  await requireArea("platform");

  const templateKey = str(fd, "templateKey", 60);
  const def = templateByKey(templateKey);
  const values = readValues(fd);
  const title = str(fd, "title", 160) || def.label;

  // Server-authoritative render — the client-supplied SVG is never trusted.
  const svg = renderTemplate(def.key, values);

  const asset = await db.marketingAsset.create({
    data: {
      kind: def.kind as MarketingAssetKind,
      title,
      format: def.format,
      width: def.width,
      height: def.height,
      templateKey: def.key,
      paramsJson: values,
      svg,
    },
  });

  await logEvent("marketing.asset.created", { assetId: asset.id, templateKey: def.key });
  revalidatePath(ASSETS);
  revalidatePath(STUDIO);
  return { ok: true, id: asset.id };
}

export async function deleteAsset(id: string): Promise<ActionState> {
  await requireArea("platform");
  if (!id) return { error: "Missing asset id." };
  // Detach from any posts first (SetNull also covers this, but be explicit).
  await db.marketingPost.updateMany({ where: { assetId: id }, data: { assetId: null } });
  await db.marketingAsset.delete({ where: { id } }).catch(() => null);
  await logEvent("marketing.asset.deleted", { assetId: id });
  revalidatePath(ASSETS);
  revalidatePath(CALENDAR);
  return { ok: true };
}

/**
 * Optional AI caption. Degrades gracefully: with no effective key it returns a
 * friendly hint instead of throwing. Read-only — writes nothing.
 */
export async function generateCaption(input: {
  templateKey: string;
  values: Partial<TemplateValues>;
  channel?: string;
}): Promise<{ caption?: string; error?: string }> {
  const user = await requireArea("platform");
  const owner = await db.user.findUnique({
    where: { id: user.id },
    select: { anthropicKeyEnc: true },
  });
  const key = effectiveKeyFor(owner);
  if (!key) {
    return { error: "Add an Anthropic API key in Settings to generate captions with AI." };
  }

  const def = templateByKey(input.templateKey);
  const v = input.values ?? {};
  const channel = (input.channel ?? "INSTAGRAM").toString();
  const facts = [
    `Format: ${def.label} (${def.format})`,
    v.headline ? `Headline: ${v.headline.replace(/\n/g, " ")}` : "",
    v.subhead ? `Subhead: ${v.subhead}` : "",
    v.offer ? `Offer: ${v.offer}` : "",
    v.coupon ? `Coupon code: ${v.coupon}` : "",
    v.cta ? `Call to action: ${v.cta}` : "",
    v.domain ? `Domain: ${v.domain}` : "",
  ]
    .filter(Boolean)
    .join("\n");

  try {
    const caption = await askClaude(
      key,
      [
        {
          role: "user",
          content: `Write a short, punchy social caption for a ${channel} post from Nxeon, a developer-first cloud VPS & web hosting company. Keep it under 280 characters, upbeat but not cheesy, and end with 2-4 relevant hashtags. Use the creative's details:\n\n${facts}`,
        },
      ],
      "You are a concise social-media copywriter for a technical cloud-hosting brand. Return only the caption text — no preamble, no quotes.",
      { maxTokens: 400, timeoutMs: 30_000 }
    );
    return { caption: caption.slice(0, 1000) };
  } catch {
    return { error: "AI caption generation failed. You can still write the caption by hand." };
  }
}

// ---------------------------------------------------------------------------
// Calendar / Posts
// ---------------------------------------------------------------------------

function parseChannel(v: string): MarketingChannelKind | null {
  return (CHANNELS as string[]).includes(v) ? (v as MarketingChannelKind) : null;
}

/** Parse a datetime-local value ("2026-08-10T14:30") into a Date, or null. */
function parseWhen(v: string): Date | null {
  if (!v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d;
}

/** Compose a post. Optional schedule → SCHEDULED, otherwise DRAFT. */
export async function createPost(_prev: ActionState, fd: FormData): Promise<ActionState> {
  await requireArea("platform");

  const channel = parseChannel(str(fd, "channel", 20));
  if (!channel) return { error: "Pick a valid channel." };
  const caption = str(fd, "caption", 4000);
  if (!caption) return { error: "A caption is required." };

  const assetIdRaw = str(fd, "assetId", 40);
  let assetId: string | null = null;
  if (assetIdRaw) {
    const exists = await db.marketingAsset.findUnique({ where: { id: assetIdRaw }, select: { id: true } });
    assetId = exists ? assetIdRaw : null;
  }

  const when = parseWhen(str(fd, "scheduledFor", 40));
  const status: MarketingPostStatus = when ? "SCHEDULED" : "DRAFT";

  const post = await db.marketingPost.create({
    data: { channel, caption, assetId, scheduledFor: when, status },
  });
  await logEvent("marketing.post.created", { postId: post.id, channel, status });
  revalidatePath(CALENDAR);
  return { ok: true, id: post.id };
}

/** Set / update a post's schedule. Empty clears it back to DRAFT. */
export async function schedulePost(_prev: ActionState, fd: FormData): Promise<ActionState> {
  await requireArea("platform");
  const id = str(fd, "id", 40);
  if (!id) return { error: "Missing post id." };
  const when = parseWhen(str(fd, "scheduledFor", 40));
  await db.marketingPost.update({
    where: { id },
    data: { scheduledFor: when, status: when ? "SCHEDULED" : "DRAFT" },
  });
  revalidatePath(CALENDAR);
  return { ok: true };
}

/**
 * Mark a post posted AFTER a human posted it by hand. Records the external URL
 * they paste. This never calls any platform API.
 */
export async function markPosted(_prev: ActionState, fd: FormData): Promise<ActionState> {
  await requireArea("platform");
  const id = str(fd, "id", 40);
  if (!id) return { error: "Missing post id." };
  const externalUrl = str(fd, "externalUrl", 500) || null;
  await db.marketingPost.update({
    where: { id },
    data: { status: "POSTED", postedAt: new Date(), externalUrl },
  });
  await logEvent("marketing.post.posted", { postId: id });
  revalidatePath(CALENDAR);
  return { ok: true };
}

export async function cancelPost(id: string): Promise<ActionState> {
  await requireArea("platform");
  if (!id) return { error: "Missing post id." };
  await db.marketingPost.update({ where: { id }, data: { status: "CANCELLED" } });
  revalidatePath(CALENDAR);
  return { ok: true };
}

export async function deletePost(id: string): Promise<ActionState> {
  await requireArea("platform");
  if (!id) return { error: "Missing post id." };
  await db.marketingPost.delete({ where: { id } }).catch(() => null);
  revalidatePath(CALENDAR);
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Channels (STUBS — no network, connected stays false)
// ---------------------------------------------------------------------------

/**
 * "Connect" a channel — a STUB. It records the handle + intent but keeps
 * `connected: false` with a "requires API access" note. There is no ad/social
 * API access yet, so a real connection is impossible; this only demonstrates
 * the flow and stores the handle for manual posting.
 */
export async function connectChannelStub(_prev: ActionState, fd: FormData): Promise<ActionState> {
  await requireArea("platform");
  const kind = parseChannel(str(fd, "kind", 20));
  if (!kind) return { error: "Unknown channel." };
  const handle = str(fd, "handle", 120);
  const note = "Stub only — real posting requires ad/social API access + platform app review.";
  await db.marketingChannel.upsert({
    where: { kind },
    create: { kind, handle, connected: false, note },
    update: { handle, connected: false, note },
  });
  await logEvent("marketing.channel.connect_stub", { kind, handle });
  revalidatePath(CALENDAR);
  return { ok: true };
}

export async function forgetChannel(kind: string): Promise<ActionState> {
  await requireArea("platform");
  const k = parseChannel(kind);
  if (!k) return { error: "Unknown channel." };
  await db.marketingChannel.delete({ where: { kind: k } }).catch(() => null);
  revalidatePath(CALENDAR);
  return { ok: true };
}

