"use client";

import { useActionState, useEffect, useMemo, useState, useTransition } from "react";
import Link from "next/link";
import {
  TEMPLATES,
  renderTemplate,
  templateByKey,
  type TemplateValues,
  type TemplateKey,
} from "@/lib/marketing/templates";
import {
  saveAsset,
  deleteAsset,
  generateCaption,
  type ActionState,
} from "@/lib/actions-marketing-studio";

const EMPTY: ActionState = {};

// ---------------------------------------------------------------------------
// Shared: client-side SVG → PNG rasterization (canvas). DEPLOY-SAFE — no server
// image library, no native deps. Loads the SVG as an <img>, paints it to a
// canvas at the creative's native pixel size, and downloads the PNG blob.
// ---------------------------------------------------------------------------

async function downloadPng(svg: string, width: number, height: number, filename: string): Promise<void> {
  const svgBlob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" });
  const url = URL.createObjectURL(svgBlob);
  try {
    const img = new Image();
    img.decoding = "async";
    await new Promise<void>((resolve, reject) => {
      img.onload = () => resolve();
      img.onerror = () => reject(new Error("Could not load SVG for rasterization."));
      img.src = url;
    });
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("Canvas is unavailable in this browser.");
    ctx.drawImage(img, 0, 0, width, height);
    const pngUrl: string = await new Promise((resolve, reject) => {
      canvas.toBlob((b) => (b ? resolve(URL.createObjectURL(b)) : reject(new Error("PNG encoding failed."))), "image/png");
    });
    const a = document.createElement("a");
    a.href = pngUrl;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(pngUrl);
  } finally {
    URL.revokeObjectURL(url);
  }
}

/** Inline SVG preview. The SVG is trusted (rendered by our own pure template). */
function SvgPreview({ svg, className }: { svg: string; className?: string }) {
  return (
    <div
      className={`overflow-hidden rounded-xl border border-white/[0.08] bg-[#0B1224] [&>svg]:block [&>svg]:h-auto [&>svg]:w-full ${className ?? ""}`}
      // eslint-disable-next-line react/no-danger
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}

function slugify(s: string): string {
  return (s || "nxeon-creative").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "creative";
}

function Banner({ state, okText }: { state: ActionState; okText: string }) {
  if (state?.error)
    return (
      <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{state.error}</div>
    );
  if (state?.ok)
    return (
      <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
        {okText}
      </div>
    );
  return null;
}

const FIELD_META: { key: keyof TemplateValues; label: string; multiline?: boolean; hint?: string }[] = [
  { key: "headline", label: "Headline", multiline: true, hint: "One line per row." },
  { key: "subhead", label: "Subhead" },
  { key: "offer", label: "Offer pill" },
  { key: "coupon", label: "Coupon code" },
  { key: "cta", label: "Call to action" },
  { key: "domain", label: "Domain" },
];

// ---------------------------------------------------------------------------
// Studio editor
// ---------------------------------------------------------------------------

export function StudioEditor() {
  const [templateKey, setTemplateKey] = useState<TemplateKey>(TEMPLATES[0].key);
  const def = useMemo(() => templateByKey(templateKey), [templateKey]);
  const [values, setValues] = useState<TemplateValues>(def.defaults);
  const [title, setTitle] = useState("");

  // Reset field values to the newly chosen template's defaults.
  useEffect(() => {
    setValues(def.defaults);
  }, [def]);

  const svg = useMemo(() => renderTemplate(templateKey, values), [templateKey, values]);

  const [saveState, saveAction, saving] = useActionState(saveAsset, EMPTY);

  // AI caption
  const [caption, setCaption] = useState("");
  const [aiErr, setAiErr] = useState<string | null>(null);
  const [aiPending, startAi] = useTransition();
  const [channel, setChannel] = useState("INSTAGRAM");

  const runAi = () =>
    startAi(async () => {
      setAiErr(null);
      const r = await generateCaption({ templateKey, values, channel });
      if (r.error) setAiErr(r.error);
      else setCaption(r.caption ?? "");
    });

  const setField = (k: keyof TemplateValues, val: string) => setValues((v) => ({ ...v, [k]: val }));

  return (
    <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,420px)]">
      {/* Editor column */}
      <div className="space-y-5">
        <div className="card p-5">
          <label className="label">Template</label>
          <div className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-4">
            {TEMPLATES.map((t) => (
              <button
                key={t.key}
                type="button"
                onClick={() => setTemplateKey(t.key)}
                className={`rounded-xl border px-3 py-2.5 text-left text-xs transition-colors ${
                  t.key === templateKey
                    ? "border-brand-500/50 bg-brand-500/15 text-brand-100"
                    : "border-white/[0.08] bg-white/[0.02] text-slate-300 hover:bg-white/[0.05]"
                }`}
              >
                <span className="block font-semibold">{t.label}</span>
                <span className="mt-0.5 block text-[11px] text-slate-500">{t.format}</span>
              </button>
            ))}
          </div>
        </div>

        <div className="card space-y-4 p-5">
          <p className="section-label">Content</p>
          {FIELD_META.map((f) =>
            f.multiline ? (
              <div key={f.key}>
                <label className="label">{f.label}</label>
                <textarea
                  className="input min-h-[80px]"
                  value={values[f.key]}
                  onChange={(e) => setField(f.key, e.target.value)}
                />
                {f.hint && <p className="mt-1 text-xs text-slate-500">{f.hint}</p>}
              </div>
            ) : (
              <div key={f.key}>
                <label className="label">{f.label}</label>
                <input className="input" value={values[f.key]} onChange={(e) => setField(f.key, e.target.value)} />
              </div>
            )
          )}
        </div>

        {/* AI caption */}
        <div className="card space-y-3 p-5">
          <div className="flex items-center justify-between">
            <p className="section-label">AI caption (optional)</p>
            <select
              className="input h-8 w-auto py-0 text-xs"
              value={channel}
              onChange={(e) => setChannel(e.target.value)}
            >
              {["INSTAGRAM", "FACEBOOK", "REDDIT", "X", "BLOG"].map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </select>
          </div>
          <button type="button" className="btn-secondary" disabled={aiPending} onClick={runAi}>
            {aiPending ? "Writing…" : "Generate caption with Claude"}
          </button>
          {aiErr && (
            <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
              {aiErr}
            </div>
          )}
          {caption && (
            <div className="space-y-2">
              <textarea className="input min-h-[90px]" value={caption} onChange={(e) => setCaption(e.target.value)} />
              <button
                type="button"
                className="btn-ghost px-3 py-1.5 text-xs"
                onClick={() => navigator.clipboard?.writeText(caption)}
              >
                Copy caption
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Preview + actions column */}
      <div className="space-y-4">
        <div className="sticky top-4 space-y-4">
          <SvgPreview svg={svg} />
          <p className="text-center text-xs text-slate-500">
            {def.format} · live preview
          </p>

          <div className="card space-y-3 p-4">
            <form action={saveAction} className="space-y-3">
              <Banner state={saveState} okText="Saved to Assets." />
              <input type="hidden" name="templateKey" value={templateKey} />
              {(Object.keys(values) as (keyof TemplateValues)[]).map((k) => (
                <input key={k} type="hidden" name={k} value={values[k]} />
              ))}
              <div>
                <label className="label">Asset title</label>
                <input
                  className="input"
                  name="title"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  placeholder={def.label}
                  maxLength={160}
                />
              </div>
              <button className="btn-primary w-full" disabled={saving}>
                {saving ? "Saving…" : "Save to Assets"}
              </button>
            </form>

            <button
              type="button"
              className="btn-secondary w-full"
              onClick={() => downloadPng(svg, def.width, def.height, `${slugify(title || def.label)}.png`)}
            >
              Download PNG
            </button>
            <p className="text-center text-[11px] text-slate-500">
              PNG is rasterized in your browser — {def.width}×{def.height}.
            </p>
          </div>

          <Link href="/admin/marketing/assets" className="block text-center text-xs text-brand-300 hover:underline">
            View saved assets →
          </Link>
        </div>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Assets gallery
// ---------------------------------------------------------------------------

export type AssetView = {
  id: string;
  title: string;
  format: string;
  kind: string;
  templateKey: string;
  width: number;
  height: number;
  svg: string;
  createdAt: string;
};

export function AssetGallery({ assets }: { assets: AssetView[] }) {
  if (assets.length === 0) {
    return (
      <div className="card flex flex-col items-center justify-center py-14 text-center">
        <h3 className="text-base font-semibold">No saved assets yet</h3>
        <p className="mt-1 max-w-sm text-sm text-slate-400">
          Head to the Studio, design a creative, and hit “Save to Assets”.
        </p>
        <Link href="/admin/marketing/studio" className="btn-primary mt-5">
          Open Studio
        </Link>
      </div>
    );
  }
  return (
    <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">
      {assets.map((a) => (
        <AssetCard key={a.id} asset={a} />
      ))}
    </div>
  );
}

function AssetCard({ asset }: { asset: AssetView }) {
  const [pending, start] = useTransition();
  const [confirming, setConfirming] = useState(false);
  return (
    <div className="card space-y-3 p-4">
      <SvgPreview svg={asset.svg} />
      <div>
        <p className="truncate font-medium text-white">{asset.title}</p>
        <p className="text-xs text-slate-500">
          {asset.format} · {new Date(asset.createdAt).toLocaleDateString()}
        </p>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <button
          className="btn-secondary px-3 py-1.5 text-xs"
          onClick={() => downloadPng(asset.svg, asset.width, asset.height, `${slugify(asset.title)}.png`)}
        >
          Download PNG
        </button>
        <Link
          href={`/admin/marketing/calendar?assetId=${asset.id}`}
          className="btn-ghost px-3 py-1.5 text-xs"
        >
          Use in post
        </Link>
        <span className="ml-auto">
          {confirming ? (
            <span className="flex items-center gap-2">
              <button
                className="btn-danger px-3 py-1.5 text-xs"
                disabled={pending}
                onClick={() => start(async () => void (await deleteAsset(asset.id)))}
              >
                {pending ? "Deleting…" : "Confirm"}
              </button>
              <button className="btn-ghost px-2 py-1.5 text-xs" onClick={() => setConfirming(false)}>
                Cancel
              </button>
            </span>
          ) : (
            <button className="btn-danger px-3 py-1.5 text-xs" onClick={() => setConfirming(true)}>
              Delete
            </button>
          )}
        </span>
      </div>
    </div>
  );
}

"use client";

import { useActionState, useEffect, useRef, useState, useTransition } from "react";
import {
  createPost,
  schedulePost,
  markPosted,
  cancelPost,
  deletePost,
  connectChannelStub,
  forgetChannel,
  type ActionState,
} from "@/lib/actions-marketing-studio";
import { downloadPng, SvgPreview, slugify } from "./StudioClient";

const EMPTY: ActionState = {};
const CHANNELS = ["INSTAGRAM", "FACEBOOK", "REDDIT", "X", "BLOG"] as const;

export type AssetOption = {
  id: string;
  title: string;
  format: string;
  svg: string;
  width: number;
  height: number;
};

export type PostView = {
  id: string;
  channel: string;
  caption: string;
  status: string;
  scheduledFor: string | null;
  postedAt: string | null;
  externalUrl: string | null;
  createdAt: string;
  asset: AssetOption | null;
};

export type ChannelView = {
  kind: string;
  handle: string;
  connected: boolean;
  note: string;
};

function Banner({ state, okText }: { state: ActionState; okText: string }) {
  if (state?.error)
    return <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{state.error}</div>;
  if (state?.ok)
    return <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">{okText}</div>;
  return null;
}

const STATUS_TONE: Record<string, string> = {
  DRAFT: "border-white/10 bg-white/[0.05] text-slate-300",
  SCHEDULED: "border-brand-500/40 bg-brand-500/10 text-brand-300",
  POSTED: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300",
  CANCELLED: "border-red-500/40 bg-red-500/10 text-red-300",
};

function StatusPill({ status }: { status: string }) {
  return (
    <span className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium ${STATUS_TONE[status] ?? STATUS_TONE.DRAFT}`}>
      {status.toLowerCase()}
    </span>
  );
}

// ---------------------------------------------------------------------------
// Composer
// ---------------------------------------------------------------------------

export function PostComposer({ assets, presetAssetId }: { assets: AssetOption[]; presetAssetId?: string }) {
  const [state, action, pending] = useActionState(createPost, EMPTY);
  const ref = useRef<HTMLFormElement>(null);
  const [assetId, setAssetId] = useState(presetAssetId ?? "");
  useEffect(() => {
    if (state?.ok) {
      ref.current?.reset();
      setAssetId("");
    }
  }, [state]);

  return (
    <form ref={ref} action={action} className="card space-y-4 p-5">
      <p className="section-label">Compose post</p>
      <Banner state={state} okText="Post created." />
      <div className="grid gap-4 sm:grid-cols-2">
        <div>
          <label className="label">Channel</label>
          <select className="input" name="channel" defaultValue="INSTAGRAM">
            {CHANNELS.map((c) => (
              <option key={c} value={c}>
                {c}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="label">Schedule for (optional)</label>
          <input className="input" type="datetime-local" name="scheduledFor" />
        </div>
      </div>
      <div>
        <label className="label">Creative (optional)</label>
        <select className="input" name="assetId" value={assetId} onChange={(e) => setAssetId(e.target.value)}>
          <option value="">No creative</option>
          {assets.map((a) => (
            <option key={a.id} value={a.id}>
              {a.title} · {a.format}
            </option>
          ))}
        </select>
      </div>
      <div>
        <label className="label">Caption</label>
        <textarea className="input min-h-[120px]" name="caption" required maxLength={4000} placeholder="Write your caption…" />
      </div>
      <p className="text-xs text-slate-500">
        Nothing is posted automatically. Compose here, then post by hand and record the result below.
      </p>
      <div className="flex justify-end">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Create post"}
        </button>
      </div>
    </form>
  );
}

// ---------------------------------------------------------------------------
// Post list + row actions
// ---------------------------------------------------------------------------

export function PostList({ posts }: { posts: PostView[] }) {
  if (posts.length === 0) {
    return (
      <div className="card py-10 text-center text-sm text-slate-400">
        No posts yet. Compose one above to build your queue.
      </div>
    );
  }
  return (
    <div className="space-y-3">
      {posts.map((p) => (
        <PostRow key={p.id} post={p} />
      ))}
    </div>
  );
}

function PostRow({ post }: { post: PostView }) {
  const [scheduleState, scheduleAction, scheduling] = useActionState(schedulePost, EMPTY);
  const [postedState, postedAction, postingMark] = useActionState(markPosted, EMPTY);
  const [pending, start] = useTransition();
  const [mode, setMode] = useState<null | "schedule" | "posted">(null);
  const [copied, setCopied] = useState(false);

  const doExport = () => {
    navigator.clipboard?.writeText(post.caption).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    });
    if (post.asset) {
      downloadPng(post.asset.svg, post.asset.width, post.asset.height, `${slugify(post.asset.title)}.png`);
    }
  };

  const terminal = post.status === "POSTED" || post.status === "CANCELLED";

  return (
    <div className="card p-4">
      <div className="flex flex-wrap items-start gap-4">
        {post.asset && (
          <div className="w-28 shrink-0">
            <SvgPreview svg={post.asset.svg} />
          </div>
        )}
        <div className="min-w-0 flex-1 space-y-2">
          <div className="flex flex-wrap items-center gap-2">
            <span className="rounded-md border border-white/10 bg-white/[0.04] px-2 py-0.5 text-xs font-medium text-slate-300">
              {post.channel}
            </span>
            <StatusPill status={post.status} />
            {post.scheduledFor && post.status === "SCHEDULED" && (
              <span className="text-xs text-brand-300">for {new Date(post.scheduledFor).toLocaleString()}</span>
            )}
            {post.postedAt && (
              <span className="text-xs text-emerald-300">posted {new Date(post.postedAt).toLocaleString()}</span>
            )}
          </div>
          <p className="whitespace-pre-wrap break-words text-sm text-slate-200">{post.caption}</p>
          {post.externalUrl && (
            <a href={post.externalUrl} target="_blank" rel="noreferrer" className="text-xs text-brand-300 hover:underline">
              {post.externalUrl}
            </a>
          )}

          {/* Inline forms */}
          {mode === "schedule" && !terminal && (
            <form action={scheduleAction} className="flex flex-wrap items-end gap-2 pt-1">
              <input type="hidden" name="id" value={post.id} />
              <div>
                <label className="label">Schedule for</label>
                <input
                  className="input"
                  type="datetime-local"
                  name="scheduledFor"
                  defaultValue={post.scheduledFor ? toLocalInput(post.scheduledFor) : ""}
                />
              </div>
              <button className="btn-primary px-3 py-1.5 text-xs" disabled={scheduling}>
                {scheduling ? "Saving…" : "Save schedule"}
              </button>
              <button type="button" className="btn-ghost px-2 py-1.5 text-xs" onClick={() => setMode(null)}>
                Cancel
              </button>
            </form>
          )}
          {scheduleState?.error && <p className="text-xs text-red-400">{scheduleState.error}</p>}

          {mode === "posted" && !terminal && (
            <form action={postedAction} className="flex flex-wrap items-end gap-2 pt-1">
              <input type="hidden" name="id" value={post.id} />
              <div className="min-w-[240px] flex-1">
                <label className="label">Posted URL (optional)</label>
                <input className="input" name="externalUrl" placeholder="https://instagram.com/p/…" maxLength={500} />
              </div>
              <button className="btn-primary px-3 py-1.5 text-xs" disabled={postingMark}>
                {postingMark ? "Saving…" : "Confirm posted"}
              </button>
              <button type="button" className="btn-ghost px-2 py-1.5 text-xs" onClick={() => setMode(null)}>
                Cancel
              </button>
            </form>
          )}
          {postedState?.error && <p className="text-xs text-red-400">{postedState.error}</p>}

          {/* Action bar */}
          <div className="flex flex-wrap items-center gap-2 pt-1">
            <button type="button" className="btn-ghost px-3 py-1.5 text-xs" onClick={doExport}>
              {copied ? "Copied!" : post.asset ? "Export (copy + PNG)" : "Copy caption"}
            </button>
            {!terminal && (
              <button type="button" className="btn-secondary px-3 py-1.5 text-xs" onClick={() => setMode(mode === "schedule" ? null : "schedule")}>
                {post.status === "SCHEDULED" ? "Reschedule" : "Schedule"}
              </button>
            )}
            {!terminal && (
              <button type="button" className="btn-secondary px-3 py-1.5 text-xs" onClick={() => setMode(mode === "posted" ? null : "posted")}>
                Mark posted
              </button>
            )}
            {!terminal && (
              <button
                type="button"
                className="btn-ghost px-3 py-1.5 text-xs text-amber-300"
                disabled={pending}
                onClick={() => start(async () => void (await cancelPost(post.id)))}
              >
                Cancel post
              </button>
            )}
            <button
              type="button"
              className="btn-danger ml-auto px-3 py-1.5 text-xs"
              disabled={pending}
              onClick={() => start(async () => void (await deletePost(post.id)))}
            >
              Delete
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

/** Convert an ISO string to the value a datetime-local input expects. */
function toLocalInput(iso: string): string {
  const d = new Date(iso);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

// ---------------------------------------------------------------------------
// Channels (stubs)
// ---------------------------------------------------------------------------

export function ChannelsPanel({ channels }: { channels: ChannelView[] }) {
  const byKind = new Map(channels.map((c) => [c.kind, c]));
  return (
    <div className="card p-5">
      <p className="section-label">Channels</p>
      <p className="mt-1 mb-4 text-xs text-slate-500">
        Connectors are stubs — Nxeon has no ad/social posting API access yet, so “Connect” only records the handle and
        stays disconnected. Post by hand, then mark posts posted above.
      </p>
      <div className="space-y-3">
        {CHANNELS.map((kind) => (
          <ChannelRow key={kind} kind={kind} channel={byKind.get(kind)} />
        ))}
      </div>
    </div>
  );
}

function ChannelRow({ kind, channel }: { kind: string; channel?: ChannelView }) {
  const [state, action, pending] = useActionState(connectChannelStub, EMPTY);
  const [forgetting, startForget] = useTransition();
  const [open, setOpen] = useState(false);

  return (
    <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <span className="font-medium text-white">{kind}</span>
          {channel?.handle && <span className="text-xs text-slate-400">{channel.handle}</span>}
          <span className="inline-flex items-center rounded-full border border-amber-500/40 bg-amber-500/10 px-2 py-0.5 text-[11px] font-medium text-amber-300">
            disconnected
          </span>
        </div>
        <div className="flex items-center gap-2">
          <button type="button" className="btn-secondary px-3 py-1.5 text-xs" onClick={() => setOpen((o) => !o)}>
            {channel ? "Edit handle" : "Connect"}
          </button>
          {channel && (
            <button
              type="button"
              className="btn-ghost px-2 py-1.5 text-xs"
              disabled={forgetting}
              onClick={() => startForget(async () => void (await forgetChannel(kind)))}
            >
              Forget
            </button>
          )}
        </div>
      </div>
      {open && (
        <form action={action} className="mt-3 flex flex-wrap items-end gap-2">
          <input type="hidden" name="kind" value={kind} />
          <div className="min-w-[200px] flex-1">
            <label className="label">Handle / profile</label>
            <input className="input" name="handle" defaultValue={channel?.handle} placeholder="@nxeoncloud" maxLength={120} />
          </div>
          <button className="btn-primary px-3 py-1.5 text-xs" disabled={pending}>
            {pending ? "Saving…" : "Save (stub)"}
          </button>
        </form>
      )}
      {state?.error && <p className="mt-2 text-xs text-red-400">{state.error}</p>}
      {channel?.note && <p className="mt-2 text-[11px] text-slate-500">{channel.note}</p>}
    </div>
  );
}

