import { requireArea } from "@/lib/rbac";
import { PageHeader } from "@/components/ui/primitives";
import { StudioEditor } from "@/components/admin/marketing/StudioClient";

export const dynamic = "force-dynamic";

/**
 * Creative Studio — design an on-brand SVG creative, save it to Assets, and
 * download a PNG rasterized entirely in the browser (canvas). No server-side
 * image library is involved.
 */
export default async function MarketingStudioPage() {
  await requireArea("platform");
  return (
    <div className="space-y-6">
      <PageHeader
        title="Studio"
        sub="Design on-brand social creatives. Save to Assets and download a browser-rendered PNG."
