import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader } from "@/components/ui/primitives";
import { AssetGallery, type AssetView } from "@/components/admin/marketing/StudioClient";

export const dynamic = "force-dynamic";

/** Assets library — every saved creative, with inline preview + PNG download + delete. */
export default async function MarketingAssetsPage() {
  await requireArea("platform");

  const rows = await db.marketingAsset.findMany({ orderBy: { createdAt: "desc" }, take: 200 });
  const assets: AssetView[] = rows.map((a) => ({
    id: a.id,
    title: a.title,
    format: a.format,
    kind: a.kind,
    templateKey: a.templateKey,
    width: a.width,
    height: a.height,
    svg: a.svg,
    createdAt: a.createdAt.toISOString(),
  }));

  return (
    <div className="space-y-6">
      <PageHeader title="Assets" sub={`${assets.length} saved creative${assets.length === 1 ? "" : "s"}.`} />
      <AssetGallery assets={assets} />
    </div>
  );
}

import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader } from "@/components/ui/primitives";
import {
  PostComposer,
  PostList,
  ChannelsPanel,
  type AssetOption,
  type PostView,
  type ChannelView,
} from "@/components/admin/marketing/CalendarClient";

export const dynamic = "force-dynamic";

/**
 * Calendar / Posting queue — compose posts, schedule them, and mark them posted
 * by hand. Channel connectors are stubs (no ad/social API access yet); nothing
 * is dispatched automatically.
 */
export default async function MarketingCalendarPage({
  searchParams,
}: {
  searchParams: Promise<{ assetId?: string }>;
}) {
  await requireArea("platform");
  const { assetId } = await searchParams;

  const [assetRows, postRows, channelRows] = await Promise.all([
    db.marketingAsset.findMany({ orderBy: { createdAt: "desc" }, take: 200 }),
    db.marketingPost.findMany({
      orderBy: [{ scheduledFor: "asc" }, { createdAt: "desc" }],
      include: { asset: true },
      take: 300,
    }),
    db.marketingChannel.findMany(),
  ]);

  const assets: AssetOption[] = assetRows.map((a) => ({
    id: a.id,
    title: a.title,
    format: a.format,
    svg: a.svg,
    width: a.width,
    height: a.height,
  }));

  const posts: PostView[] = postRows.map((p) => ({
    id: p.id,
    channel: p.channel,
    caption: p.caption,
    status: p.status,
    scheduledFor: p.scheduledFor ? p.scheduledFor.toISOString() : null,
    postedAt: p.postedAt ? p.postedAt.toISOString() : null,
    externalUrl: p.externalUrl,
    createdAt: p.createdAt.toISOString(),
    asset: p.asset
      ? { id: p.asset.id, title: p.asset.title, format: p.asset.format, svg: p.asset.svg, width: p.asset.width, height: p.asset.height }
      : null,
  }));

  const channels: ChannelView[] = channelRows.map((c) => ({
    kind: c.kind,
    handle: c.handle,
    connected: c.connected,
    note: c.note,
  }));

  const counts = {
    draft: posts.filter((p) => p.status === "DRAFT").length,
    scheduled: posts.filter((p) => p.status === "SCHEDULED").length,
    posted: posts.filter((p) => p.status === "POSTED").length,
  };

  return (
    <div className="space-y-6">
      <PageHeader
        title="Calendar"
        sub={`${counts.draft} draft · ${counts.scheduled} scheduled · ${counts.posted} posted. Manual posting only — no auto-dispatch.`}
      />

      <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,360px)]">
        <div className="space-y-6">
          <PostComposer assets={assets} presetAssetId={assetId} />
          <PostList posts={posts} />
        </div>
        <ChannelsPanel channels={channels} />
      </div>
    </div>
  );
}

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  TEMPLATES,
  renderTemplate,
  templateByKey,
  escapeXml,
  type TemplateValues,
} from "../lib/marketing/templates.ts";

/**
 * The Studio's creative templates are the one piece of the Marketing Hub that is
 * PURE (no DB, no clock, no network), so it is the piece worth pinning with
 * assertions. Two properties matter most:
 *
 *  1. Every template renders a well-formed, self-contained SVG at its declared
 *     pixel size — because the browser rasterizes THAT SVG to PNG via canvas, a
 *     malformed root or a wrong width/height silently corrupts every download.
 *
 *  2. User-supplied field values can never break out of the SVG. renderTemplate
 *     re-runs server-side on save, so an unescaped `<` or `"` in a headline would
 *     be stored and later re-served — a stored-XSS hazard. The templates escape
 *     the five XML-significant characters; this file proves it stays that way.
 */

test("escapeXml neutralizes every XML-significant character", () => {
  assert.equal(escapeXml(`<b>"x" & 'y'`), "&lt;b&gt;&quot;x&quot; &amp; &#39;y&#39;");
  assert.equal(escapeXml(""), "");
  // Nullish input must not throw and must yield an empty string.
  assert.equal(escapeXml(undefined as unknown as string), "");
});

test("every template renders a self-contained SVG at its declared size", () => {
  assert.ok(TEMPLATES.length >= 4, "expected the four brief templates");
  for (const t of TEMPLATES) {
    const svg = renderTemplate(t.key, {});
    assert.ok(svg.startsWith("<svg"), `${t.key}: SVG must start with <svg`);
    assert.ok(svg.trimEnd().endsWith("</svg>"), `${t.key}: SVG must be closed`);
    assert.ok(svg.includes('xmlns="http://www.w3.org/2000/svg"'), `${t.key}: needs the SVG namespace to rasterize`);
    assert.ok(svg.includes(`width="${t.width}"`), `${t.key}: width must match the declared size`);
    assert.ok(svg.includes(`height="${t.height}"`), `${t.key}: height must match the declared size`);
    assert.ok(svg.includes(`viewBox="0 0 ${t.width} ${t.height}"`), `${t.key}: needs a matching viewBox`);
    // Self-contained: no external references that a canvas would refuse to taint-load.
    assert.ok(!/xlink:href|href="http|<image\b/.test(svg), `${t.key}: must not reference external assets`);
    // The declared kind matches the Prisma enum literal set.
    assert.ok(["POST", "STORY", "BANNER", "VIDEO_FRAME"].includes(t.kind), `${t.key}: unexpected kind`);
  }
});

test("malicious field values are escaped, not injected as markup", () => {
  const evil: TemplateValues = {
    headline: `</text><script>alert(1)</script>`,
    subhead: `"onload="alert(2)`,
    offer: `<foreignObject>`,
    coupon: `A&B`,
    cta: `<rect/>`,
    domain: `evil".com`,
  };
  for (const t of TEMPLATES) {
    const svg = renderTemplate(t.key, evil);
    assert.ok(!svg.includes("<script>"), `${t.key}: raw <script> leaked into the SVG`);
    assert.ok(!svg.includes("</text><script"), `${t.key}: headline broke out of its <text>`);
    assert.ok(svg.includes("&lt;script&gt;"), `${t.key}: script text should appear escaped`);
    assert.ok(svg.includes("A&amp;B"), `${t.key}: ampersand in coupon must be escaped`);
  }
});

test("unknown template key falls back to the first template", () => {
  const fallback = templateByKey("does-not-exist");
  assert.equal(fallback.key, TEMPLATES[0].key);
  // renderTemplate is total: it never throws on a bad key.
  const svg = renderTemplate("does-not-exist", {});
  assert.ok(svg.startsWith("<svg"));
});

test("caller values override defaults; omitted fields keep the template default", () => {
  const def = TEMPLATES[0];
  const svg = renderTemplate(def.key, { domain: "example.test" });
  assert.ok(svg.includes("example.test"), "explicit domain should render");
  // The offer default should still be present since it was not overridden.
  assert.ok(svg.includes(escapeXml(def.defaults.offer.slice(0, 6))), "default offer should survive a partial override");
});

